// The established OpenNetwork API is projected from the same resolved model as every package.
import { readFileSync, readdirSync } from "node:fs";
import {
  ROOT,
  isObject,
  stableJson,
  type Json,
  type JsonObject,
} from "../dtcg.ts";
import { nd, type Model, type Token } from "../model.ts";
import { camel, colorOf, hex8 } from "./native.ts";

const HEADER =
  "// GENERATED by nddev-opennetwork-design-system (`just generate`). Do not edit.\n";
const spaceNames: Record<string, string> = {
  "0": "zero",
  "1": "one",
  "2": "two",
  "3": "three",
  "4": "four",
  "6": "six",
  "8": "eight",
  "12": "twelve",
  "16": "sixteen",
  "24": "twentyFour",
};
const pixels = (v: Json | undefined): number => {
  if (!isObject(v) || typeof v["value"] !== "number")
    throw new Error("Expected a dimension");
  return v["value"] * (v["unit"] === "rem" ? 16 : 1);
};
const scalar = (v: Json | undefined): number => {
  if (typeof v !== "number" || !Number.isFinite(v))
    throw new Error("Expected a number");
  return v;
};

export function emitOpenNetwork(model: Model): Map<string, string> {
  const out = new Map<string, string>();
  const at = model.get({
    direction: "on",
    theme: "dark",
    platform: "web",
    density: "comfortable",
  });
  const take = (id: string): Token => {
    const token = at[id];
    if (!token) throw new Error(`OpenNetwork API requires ${id}`);
    return token;
  };
  const fields = model.ids.filter((id) =>
    /^(surface\.(base|raised|sunken|overlay)|text\.(primary|secondary|tertiary)|border\.(subtle|control|strong)|focus\.ring|status\.(success|warning|danger|info)\.(text|border|subtle)|accent\.(brand|text|heading|fill|fill-hover|fill-active|on-fill|border|outline|label|edge|subtle))$/.test(
      id,
    ),
  );
  const dart: string[] = [
    HEADER,
    "import 'package:flutter/material.dart';",
    "",
    "class OpenNetworkPalette {",
    "  const OpenNetworkPalette({",
    ...fields.map((id) => `    required this.${camel(id)},`),
    "  });",
    ...fields.map((id) => `  final Color ${camel(id)};`),
    "}",
    "",
    "abstract final class OpenNetworkColors {",
  ];
  const legacy: JsonObject = {
    $description:
      "Generated compatibility view. Canonical source: tokens/registry.json and the DTCG source files. Do not edit.",
  };
  for (const theme of model.themes) {
    const set = model.get({
      theme: theme.id,
      direction: "on",
      platform: "web",
    });
    dart.push(`  static const ${camel(theme.id)} = OpenNetworkPalette(`);
    const group: JsonObject = {};
    for (const id of fields) {
      const token = set[id];
      if (!token) throw new Error(`Missing ${id} in ${theme.id}`);
      const value = colorOf(token, set);
      dart.push(`    ${camel(id)}: Color(0x${hex8(value)}),`);
      group[id.replaceAll(".", "-")] = {
        $type: "color",
        $value: "#" + hex8(value).slice(2),
      };
    }
    dart.push("  );");
    legacy[theme.id === "dark" ? "color" : `${theme.id}-color`] = group;
  }
  dart.push("}", "");
  const group = (
    name: string,
    values: Record<string, number | string[]>,
  ): void => {
    dart.push(`abstract final class OpenNetwork${name} {`);
    for (const [key, value] of Object.entries(values))
      dart.push(
        `  static const ${key} = ${Array.isArray(value) ? `<String>[${value.map((s) => JSON.stringify(s)).join(", ")}]` : Number.isInteger(value) ? `${value}.0` : String(value)};`,
      );
  };
  const end = (): void => {
    dart.push("}", "");
  };
  group(
    "Spacing",
    Object.fromEntries(
      Object.entries(spaceNames).map(([key, name]) => [
        name,
        pixels(take(`space.${key}`).$value),
      ]),
    ),
  );
  end();
  group(
    "Radii",
    Object.fromEntries(
      ["sm", "md", "lg", "xl", "2xl", "pill"].map((key) => [
        key === "2xl" ? "xxl" : key,
        pixels(take(`radius.${key}`).$value),
      ]),
    ),
  );
  end();
  group(
    "Sizes",
    Object.fromEntries(
      [
        "target-min",
        "control-md",
        "control-lg",
        "field",
        "icon",
        "icon-md",
        "brand",
        "dock-tile",
      ].map((key) => [camel(key), pixels(take(`size.${key}`).$value)]),
    ),
  );
  end();
  const typography: Record<string, number | string[]> = {
    fontFamily: ["IBM Plex Sans", "sans-serif"],
    viewportMin: 320,
    viewportMax: 1920,
  };
  const sizes: string[] = [];
  for (const role of [
    "display",
    "h1",
    "h2",
    "h3",
    "h4",
    "body-lg",
    "body",
    "label",
    "caption",
  ]) {
    const token = take(`text-size.${role}`);
    const fluid = nd(token)["fluid"];
    const min = isObject(fluid) ? pixels(fluid["min"]) : pixels(token.$value);
    const max = pixels(token.$value);
    const vp =
      isObject(fluid) && Array.isArray(fluid["viewport"])
        ? fluid["viewport"]
        : [320, 1440];
    typography[`${camel(role)}Min`] = min;
    typography[`${camel(role)}Max`] = max;
    typography[`${camel(role)}Leading`] = scalar(
      take(`text-leading.${role}`).$value,
    );
    sizes.push(
      `      '${camel(role)}' => ${min} + (${max} - ${min}) * ((width - ${String(scalar(vp[0]))}) / (${String(scalar(vp[1]))} - ${String(scalar(vp[0]))})).clamp(0.0, 1.0),`,
    );
  }
  for (const key of ["regular", "medium", "semibold"])
    typography[`weight${key[0]?.toUpperCase()}${key.slice(1)}`] = scalar(
      take(`weight.${key}`).$value,
    );
  group("Typography", typography);
  dart.push(
    "  /// The canonical web type role at a viewport width, in logical pixels.",
    "  static double sizeAt(String role, double width) => switch (role) {",
    ...sizes,
    "      _ => throw ArgumentError.value(role, 'role'),",
    "    };",
  );
  end();
  const duration = (id: string): number => {
    const v = take(id).$value;
    if (!isObject(v)) throw new Error(id);
    return scalar(v["value"]) * (v["unit"] === "s" ? 1000 : 1);
  };
  group("Motion", {
    uiFast: duration("duration.ui-fast"),
    ui: duration("duration.ui"),
  });
  end();
  out.set("packages/flutter/lib/src/tokens.dart", dart.join("\n"));
  out.set("tokens/tokens.json", stableJson(legacy));
  for (const name of ["theme.dart", "brand.dart", "licenses.dart"])
    out.set(
      `packages/flutter/lib/src/${name}`,
      readFileSync(`${ROOT}adapters/flutter/${name}`, "utf8"),
    );
  out.set(
    "packages/flutter/pubspec.yaml",
    readFileSync(`${ROOT}adapters/flutter/pubspec.yaml`, "utf8"),
  );
  for (const name of readdirSync(`${ROOT}tests/flutter`))
    if (name.endsWith(".dart"))
      out.set(
        `packages/flutter/test/${name}`,
        readFileSync(`${ROOT}tests/flutter/${name}`, "utf8"),
      );
  out.set(
    "packages/flutter/lib/opennetwork_design_system.dart",
    `${HEADER}library;\n\nexport 'src/brand.dart';\nexport 'src/theme.dart';\nexport 'src/tokens.dart';\nexport 'src/nd_tokens.dart';\nexport 'src/nd_theme.dart';\nexport 'src/icons.dart';\n`,
  );
  return out;
}
